<template><main class="admin-login"><div class="login-brand">MD <span>管理</span></div><section><h1>管理员登录</h1><form @submit.prevent="submit"><label>账号或邮箱<input v-model.trim="form.login" autocomplete="username" required></label><label>密码<input v-model="form.password" type="password" autocomplete="current-password" required></label><p v-if="error" class="admin-error" role="alert">{{error}}</p><button type="submit" :disabled="submitting">{{submitting?'登录中…':'登录'}}</button></form></section></main></template>
<script>import{adminProblemMessage}from'../ui/admin-model.js';export default{name:'LoginView',data:()=>({form:{login:'',password:''},submitting:false,error:''}),methods:{async submit(){this.submitting=true;this.error='';try{await this.$store.dispatch('login',{...this.form});this.form.password='';this.$router.replace(typeof this.$route.query.redirect==='string'?this.$route.query.redirect:'/tracks');}catch(problem){this.form.password='';this.error=adminProblemMessage(problem);}finally{this.submitting=false;}}}};</script>
